    /// If we find an ignored suffix on the file name, e.g. '~', we strip it and
    /// then try again without it.
    fn try_with_stripped_suffix(
        &self,
        ignored_suffixes: &IgnoredSuffixes,
        file_name: &OsStr,
        use_full_name: bool,
    ) -> Result<Option<SyntaxReferenceInSet>> {
        let syntax_set = self
            .syntax_set_cell
            .try_borrow_with(|| self.serialized_syntax_set.deserialize())?;

        let candidate = if use_full_name {
            Some(file_name)
        } else {
            Path::new(file_name).extension()
        };
        let extension = candidate.and_then(|x| x.to_str()).unwrap_or_default();
        if let Some(syntax) = syntax_set.find_syntax_by_extension(extension) {
            return Ok(Some(SyntaxReferenceInSet { syntax, syntax_set }));
        }

        let file_str = match Path::new(file_name).to_str() {
            Some(file_str) => file_str,
            None => return Ok(None),
        };
        let stripped = ignored_suffixes
            .editor_suffixes()
            .iter()
            .chain(ignored_suffixes.dpkg_suffixes().iter())
            .chain(ignored_suffixes.ucf_suffixes().iter())
            .chain(ignored_suffixes.redhat_suffixes().iter())
            .chain(ignored_suffixes.build_suffixes().iter())
            .find_map(|suffix| file_str.strip_suffix(*suffix));

        match stripped {
            Some(stripped_file_name) => self.try_with_stripped_suffix(
                ignored_suffixes,
                OsStr::new(stripped_file_name),
                use_full_name,
            ),
            None => Ok(None),
        }
    }

    fn get_first_line_syntax(
        &self,
        reader: &mut InputReader,
    ) -> Result<Option<SyntaxReferenceInSet>> {
        let syntax_set = self.get_syntax_set()?;
        Ok(String::from_utf8(reader.first_line.clone())
            .ok()
            .and_then(|l| syntax_set.find_syntax_by_first_line(&l))
            .map(|syntax| SyntaxReferenceInSet { syntax, syntax_set }))
    }
}

